const chartData = [
  { id: 'chart1', aspectRatio: 1.5 }, // Example aspect ratio
  { id: 'chart2', aspectRatio: 1.2 },
  // ... more chart data
];

chartData.forEach(chart => {
  const container = document.getElementById(chart.id);
  const containerWidth = container.offsetWidth;
  const containerHeight = containerWidth / chart.aspectRatio;
  container.style.height = `${containerHeight}px`; 
});
```

